#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXX 55
#define MAXY 55
#define MAXN 2600
#define MAXID 64

typedef struct {
    char id[MAXID];
    int area;
} Buyer;

typedef struct {
    int x1, y1, x2, y2; /* inclusive */
} Rect;

static int X, Y, n;
static Buyer buyers[MAXN];
static char board[MAXY][MAXX][MAXID];
static int owner[MAXY][MAXX];          /* assigned buyer index, -1 if unassigned */
static int signIdx[MAXY][MAXX];        /* sign -> buyer index */
static int remainingArea[MAXN];

static Rect cand[MAXN][MAXN];
static int candCnt[MAXN];

static int solvedCount;
static int answer[MAXY][MAXX];
static int impossible;

static int rectHasOnlyBuyerSigns(int b, int x1, int y1, int x2, int y2) {
    int y, x;
    for (y = y1; y <= y2; y++) {
        for (x = x1; x <= x2; x++) {
            if (signIdx[y][x] != b) return 0;
        }
    }
    return 1;
}

static int rectUnassigned(int x1, int y1, int x2, int y2) {
    int y, x;
    for (y = y1; y <= y2; y++) {
        for (x = x1; x <= x2; x++) {
            if (owner[y][x] != -1) return 0;
        }
    }
    return 1;
}

static void fillRect(int b, Rect r) {
    int y, x;
    for (y = r.y1; y <= r.y2; y++) {
        for (x = r.x1; x <= r.x2; x++) {
            owner[y][x] = b;
        }
    }
    remainingArea[b] = 0;
}

static void unfillRect(Rect r) {
    int y, x;
    for (y = r.y1; y <= r.y2; y++) {
        for (x = r.x1; x <= r.x2; x++) {
            owner[y][x] = -1;
        }
    }
}

static int allAssigned(void) {
    int i;
    for (i = 0; i < n; i++) {
        if (remainingArea[i] != 0) return 0;
    }
    return 1;
}

static void saveSolution(void) {
    int y, x;
    for (y = 0; y < Y; y++) {
        for (x = 0; x < X; x++) {
            answer[y][x] = owner[y][x];
        }
    }
}

static void dfs(void) {
    int i, j, best = -1, bestCnt = 1 << 30;

    if (impossible) return;
    if (allAssigned()) {
        solvedCount++;
        if (solvedCount == 1) saveSolution();
        else impossible = 1; /* multiple solutions */
        return;
    }

    for (i = 0; i < n; i++) {
        if (remainingArea[i] == 0) continue;
        int cnt = 0;
        for (j = 0; j < candCnt[i]; j++) {
            Rect r = cand[i][j];
            if (rectUnassigned(r.x1, r.y1, r.x2, r.y2)) cnt++;
        }
        if (cnt == 0) return; /* dead end */
        if (cnt < bestCnt) {
            bestCnt = cnt;
            best = i;
            if (cnt == 1) break;
        }
    }

    for (j = 0; j < candCnt[best]; j++) {
        Rect r = cand[best][j];
        if (!rectUnassigned(r.x1, r.y1, r.x2, r.y2)) continue;
        fillRect(best, r);
        dfs();
        unfillRect(r);
        remainingArea[best] = buyers[best].area;
        if (impossible) return;
    }
}

static int findBuyerIndex(char *s) {
    int i;
    for (i = 0; i < n; i++) {
        if (strcmp(buyers[i].id, s) == 0) return i;
    }
    return -1;
}

int main(void) {
    while (scanf("%d %d %d", &X, &Y, &n) == 3) {
        int i, x, y;
        if (X == 0 && Y == 0 && n == 0) break;

        for (i = 0; i < n; i++) {
            scanf("%s %d", buyers[i].id, &buyers[i].area);
            remainingArea[i] = buyers[i].area;
            candCnt[i] = 0;
        }

        for (y = 0; y < Y; y++) {
            for (x = 0; x < X; x++) {
                scanf("%s", board[y][x]);
            }
        }

        for (y = 0; y < Y; y++) {
            for (x = 0; x < X; x++) {
                signIdx[y][x] = findBuyerIndex(board[y][x]);
            }
        }

        impossible = 0;
        solvedCount = 0;
        for (y = 0; y < Y; y++) for (x = 0; x < X; x++) owner[y][x] = -1;

        /* Generate all candidate rectangles for each buyer:
           rectangle area must equal buyer area and all signs inside must be that buyer. */
        for (i = 0; i < n; i++) {
            int a = buyers[i].area;
            int w, h;
            for (h = 1; h <= a; h++) {
                if (a % h) continue;
                w = a / h;
                if (w > X || h > Y) continue;
                for (y = 0; y + h - 1 < Y; y++) {
                    for (x = 0; x + w - 1 < X; x++) {
                        if (rectHasOnlyBuyerSigns(i, x, y, x + w - 1, y + h - 1)) {
                            cand[i][candCnt[i]].x1 = x;
                            cand[i][candCnt[i]].y1 = y;
                            cand[i][candCnt[i]].x2 = x + w - 1;
                            cand[i][candCnt[i]].y2 = y + h - 1;
                            candCnt[i]++;
                        }
                    }
                }
            }
            if (candCnt[i] == 0) impossible = 1;
        }

        if (!impossible) dfs();

        if (impossible || solvedCount != 1) {
            printf("NA\n");
        } else {
            for (y = 0; y < Y; y++) {
                for (x = 0; x < X; x++) {
                    if (x) printf(" ");
                    printf("%s", buyers[answer[y][x]].id);
                }
                printf("\n");
            }
        }
    }
    return 0;
}

