        int buyers[101];
        char names[101][100];
        for (int i = 0; i < n; i++) {
            scanf("%d %s", &buyers[i], &names[i]);
        }

        int grid[50][50];
        for (int y = 0; y < Y; y++)
            for (int x = 0; x < X; x++)
                scanf("%d", &grid[y][x]);

        // Find bounding box for each buyer
        int minx[101], maxx[101], miny[101], maxy[101];
        int found[101] = {0};
        for (int i = 0; i < n; i++) {
            minx[i] = X; maxx[i] = -1; miny[i] = Y; maxy[i] = -1;
        }

        // map buyer id to index
        // just use buyer id directly up to 100
        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                int id = grid[y][x];
                // find index
                for (int i = 0; i < n; i++) {
                    if (buyers[i] == id) {
                        if (x < minx[i]) minx[i] = x;
                        if (x > maxx[i]) maxx[i] = x;
                        if (y < miny[i]) miny[i] = y;
                        if (y > maxy[i]) maxy[i] = y;
                        found[i] = 1;
                        break;
                    }
                }
            }
        }

        // Verify each buyer's region is a complete rectangle
        int valid = 1;
        for (int i = 0; i < n; i++) {
            if (!found[i]) { valid = 0; break; }
            for (int y = miny[i]; y <= maxy[i] && valid; y++)
                for (int x = minx[i]; x <= maxx[i] && valid; x++)
                    if (grid[y][x] != buyers[i]) valid = 0;
        }

        if (!valid) { printf("NA\n"); continue; }

        for (int i = 0; i < n; i++) {
            printf("%d %s (%d,%d)-(%d,%d)\n", buyers[i], names[i], minx[i]+1, miny[i]+1, maxx[i]+1, maxy[i]+1);
        }
    }
    return 0;
}

#include <stdio.h>
