#define MAX_X 20
#define MAX_Y 20
#define MAX_N 100

typedef struct {
    int x1, y1, x2, y2; // inclusive coordinates
    char name[21];
} Buyer;

int X, Y, n;
Buyer buyers[MAX_N];
char plot[MAX_Y][MAX_X + 1]; // plot[y][x]
char result[MAX_Y][MAX_X + 1];
int used[MAX_N];
int possible_count;
int possible_result[MAX_Y][MAX_X + 1];
int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};

void copy_result() {
    for (int y = 0; y < Y; y++) {
        strcpy(possible_result[y], result[y]);
    }
}

void dfs(int idx) {
    if (idx == n) {
        // check if all plots assigned
        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                if (result[y][x] == '.') return;
            }
        }
        possible_count++;
        if (possible_count == 1) {
            copy_result();
        }
        return;
    }

    // try to place buyer idx in all possible positions
    int w = buyers[idx].x2 - buyers[idx].x1 + 1;
    int h = buyers[idx].y2 - buyers[idx].y1 + 1;
    char *name = buyers[idx].name;

    // try all top-left corners
    for (int top = 0; top + h <= Y; top++) {
        for (int left = 0; left + w <= X; left++) {
            // check if this rectangle matches the plot signs and is empty
            int ok = 1;
            for (int y = top; y < top + h && ok; y++) {
                for (int x = left; x < left + w && ok; x++) {
                    if (result[y][x] != '.' && result[y][x] != '?') { 
                        if (result[y][x] != name[0]) ok = 0;
                    }
                    if (plot[y][x] != '*' && plot[y][x] != name[0]) ok = 0;
                }
            }
            if (!ok) continue;

            // place the rectangle
            char placed[MAX_Y][MAX_X + 1];
            memcpy(placed, result, sizeof(placed));
            for (int y = top; y < top + h; y++) {
                for (int x = left; x < left + w; x++) {
                    result[y][x] = name[0];
                }
            }
            used[idx] = 1;
            dfs(idx + 1);
            used[idx] = 0;
            memcpy(result, placed, sizeof(result));

            if (possible_count > 1) return;
        }
    }
}

int main() {
    while (1) {
        scanf("%d %d %d", &X, &Y, &n);
        if (X == 0 && Y == 0 && n == 0) break;

        for (int i = 0; i < n; i++) {
            scanf("%s %d %d %d %d", buyers[i].name, &buyers[i].x1, &buyers[i].y1, &buyers[i].x2, &buyers[i].y2);
            // convert to 0-indexed
            buyers[i].x1--; buyers[i].y1--; buyers[i].x2--; buyers[i].y2--;
        }

        for (int y = 0; y < Y; y++) {
            scanf("%s", plot[y]);
        }

        // initialize result with '.'
        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                result[y][x] = '.';
            }
            result[y][X] = '\0';
        }

        possible_count = 0;
        memset(used, 0, sizeof(used));
        dfs(0);

        if (possible_count == 1) {
            for (int y = 0; y < Y; y++) {
                printf("%s\n", possible_result[y]);
            }
        } else {
            printf("NA\n");
        }
    }
    return 0;
}

