int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int X, Y, n;
    while (cin >> X >> Y >> n) {
        if (X == 0 && Y == 0 && n == 0) break;

        vector<int> a(n), b(n), c(n), d(n);
        vector<string> id(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i] >> b[i] >> c[i] >> d[i] >> id[i];
            // Ensure a <= c, b <= d
            if (a[i] > c[i]) swap(a[i], c[i]);
            if (b[i] > d[i]) swap(b[i], d[i]);
        }

        vector<string> grid(Y);
        for (int i = 0; i < Y; i++) {
            cin >> grid[i];
        }

        // For each plot (x,y), find which buyer rectangles contain it
        vector<vector<int>> possible(Y, vector<int>(X, -1));
        bool ambiguous = false;

        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                int cnt = 0;
                int idx = -1;
                for (int i = 0; i < n; i++) {
                    if (a[i] <= x && x <= c[i] && b[i] <= y && y <= d[i]) {
                        cnt++;
                        idx = i;
                    }
                }
                if (cnt == 0) {
                    // Plot not covered by any buyer rectangle
                    ambiguous = true;
                } else if (cnt > 1) {
                    ambiguous = true;
                } else {
                    possible[y][x] = idx;
                }
            }
        }

        if (ambiguous) {
            cout << "NA\n";
            continue;
        }

        // Now check that the assignment is consistent:
        // For each buyer, the set of plots assigned to them must form exactly their rectangle.
        for (int i = 0; i < n; i++) {
            for (int y = b[i]; y <= d[i]; y++) {
                for (int x = a[i]; x <= c[i]; x++) {
                    if (possible[y][x] != i) {
                        ambiguous = true;
                    }
                }
            }
            // Also ensure no extra plots outside their rectangle are assigned to them
            // (already ensured by the previous loop since each plot assigned to exactly one buyer)
        }

        if (ambiguous) {
            cout << "NA\n";
            continue;
        }

        // Output the grid with IDs
        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                if (x > 0) cout << " ";
                cout << id[possible[y][x]];
            }
            cout << "\n";
        }
    }

    return 0;
}

