int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int X, Y, n;
        cin >> X >> Y >> n;
        if (!cin) return 0;
        if (X == 0 && Y == 0 && n == 0) break;

        vector<string> buyer(n);
        for (int i = 0; i < n; i++) cin >> buyer[i];

        vector<string> g(Y);
        for (int y = 0; y < Y; y++) cin >> g[y];

        // positions of each buyer's sign
        vector<pair<int,int>> pos(n, {-1,-1});
        unordered_map<string,int> id;
        id.reserve(n * 2);
        for (int i = 0; i < n; i++) id[buyer[i]] = i;

        bool bad = false;
        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                string s(1, g[y][x]);
                auto it = id.find(s);
                if (it == id.end()) {
                    bad = true;
                } else {
                    int k = it->second;
                    if (pos[k].first != -1) bad = true; // duplicated sign
                    pos[k] = {x, y};
                }
            }
        }
        for (int i = 0; i < n; i++) {
            if (pos[i].first == -1) bad = true;
        }

        if (bad) {
            for (int y = 0; y < Y; y++) cout << string(X, '?') << "\n";
            continue;
        }

        vector<vector<int>> ans(Y, vector<int>(X, -1));
        vector<vector<int>> ways(Y, vector<int>(X, 0));

        // Enumerate all partitions of the whole X*Y rectangle into n rectangles,
        // each rectangle containing exactly one sign.
        function<void(int,int,int,int, vector<int>&)> dfs =
            [&](int x1, int y1, int x2, int y2, vector<int>& idsIn) {
                int w = x2 - x1 + 1;
                int h = y2 - y1 + 1;

                if ((int)idsIn.size() == 1) {
                    int k = idsIn[0];
                    for (int y = y1; y <= y2; y++) {
                        for (int x = x1; x <= x2; x++) {
                            ways[y][x]++;
                            if (ans[y][x] == -1) ans[y][x] = k;
                            else if (ans[y][x] != k) ans[y][x] = -2; // ambiguous
                        }
                    }
                    return;
                }

                // vertical cuts
                for (int cut = x1; cut < x2; cut++) {
                    vector<int> L, R;
                    for (int k : idsIn) {
                        if (pos[k].first <= cut) L.push_back(k);
                        else R.push_back(k);
                    }
                    if (L.empty() || R.empty()) continue;
                    dfs(x1, y1, cut, y2, L);
                    dfs(cut + 1, y1, x2, y2, R);
                }

                // horizontal cuts
                for (int cut = y1; cut < y2; cut++) {
                    vector<int> U, D;
                    for (int k : idsIn) {
                        if (pos[k].second <= cut) U.push_back(k);
                        else D.push_back(k);
                    }
                    if (U.empty() || D.empty()) continue;
                    dfs(x1, y1, x2, cut, U);
                    dfs(x1, cut + 1, x2, y2, D);
                }
            };

        // The above naive DFS overcounts combinations incorrectly because
        // it mixes independent recursive results. We need to enumerate full
        // valid layouts and accumulate only complete solutions.

        fill(ans.begin(), ans.end(), vector<int>(X, -1));
        fill(ways.begin(), ways.end(), vector<int>(X, 0));

        vector<vector<int>> cur(Y, vector<int>(X, -1));
        long long totalSolutions = 0;

        function<void(int,int,int,int, vector<int>&)> solve =
            [&](int x1, int y1, int x2, int y2, vector<int>& idsIn) {
                if (idsIn.size() == 1) {
                    int k = idsIn[0];
                    for (int y = y1; y <= y2; y++)
                        for (int x = x1; x <= x2; x++)
                            cur[y][x] = k;
                    return;
                }

                // This function is only used inside enumerate().
            };

        function<void(int,int,int,int, vector<int>&)> enumerate =
            [&](int x1, int y1, int x2, int y2, vector<int>& idsIn) {
                if (idsIn.size() == 1) {
                    int k = idsIn[0];
                    for (int y = y1; y <= y2; y++)
                        for (int x = x1; x <= x2; x++)
                            cur[y][x] = k;
                    return;
                }

                bool cutFound = false;

                // Try vertical cuts
                for (int cut = x1; cut < x2; cut++) {
                    vector<int> L, R;
                    for (int k : idsIn) {
                        if (pos[k].first <= cut) L.push_back(k);
                        else R.push_back(k);
                    }
                    if (L.empty() || R.empty()) continue;
                    cutFound = true;

                    auto backup = cur;
                    enumerate(x1, y1, cut, y2, L);
                    vector<vector<int>> leftDone = cur;

                    cur = backup;
                    enumerate(cut + 1, y1, x2, y2, R);
                    vector<vector<int>> rightDone = cur;

                    // Need all combinations of left/right solutions, so do proper recursive branching instead.
                }

                // Since above approach cannot combine multiple subsolutions properly,
                // we instead return all possible fillings for a region.
            };

        // Return all possible assignments for a region as list of grids limited to that region.
        // Simpler due to small constraints in original problem.
        map<tuple<int,int,int,int, vector<int>>, vector<vector<vector<int>>>> memo;

        function<vector<vector<vector<int>>>(int,int,int,int, vector<int>)> gen =
            [&](int x1, int y1, int x2, int y2, vector<int> idsIn) -> vector<vector<vector<int>>> {
                sort(idsIn.begin(), idsIn.end());
                auto key = make_tuple(x1,y1,x2,y2,idsIn);
                auto it = memo.find(key);
                if (it != memo.end()) return it->second;

                vector<vector<vector<int>>> res;

                if (idsIn.size() == 1) {
                    vector<vector<int>> a(Y, vector<int>(X, -1));
                    int k = idsIn[0];
                    for (int y = y1; y <= y2; y++)
                        for (int x = x1; x <= x2; x++)
                            a[y][x] = k;
                    res.push_back(move(a));
                    memo[key] = res;
                    return res;
                }

                // vertical cuts
                for (int cut = x1; cut < x2; cut++) {
                    vector<int> L, R;
                    for (int k : idsIn) {
                        if (pos[k].first <= cut) L.push_back(k);
                        else R.push_back(k);
                    }
                    if (L.empty() || R.empty()) continue;
                    auto A = gen(x1, y1, cut, y2, L);
                    auto B = gen(cut + 1, y1, x2, y2, R);
                    for (auto &a : A) for (auto &b : B) {
                        vector<vector<int>> c(Y, vector<int>(X, -1));
                        for (int y = y1; y <= y2; y++) {
                            for (int x = x1; x <= x2; x++) {
                                if (x <= cut) c[y][x] = a[y][x];
                                else c[y][x] = b[y][x];
                            }
                        }
                        res.push_back(move(c));
                    }
                }

                // horizontal cuts
                for (int cut = y1; cut < y2; cut++) {
                    vector<int> U, D;
                    for (int k : idsIn) {
                        if (pos[k].second <= cut) U.push_back(k);
                        else D.push_back(k);
                    }
                    if (U.empty() || D.empty()) continue;
                    auto A = gen(x1, y1, x2, cut, U);
                    auto B = gen(x1, cut + 1, x2, y2, D);
                    for (auto &a : A) for (auto &b : B) {
                        vector<vector<int>> c(Y, vector<int>(X, -1));
                        for (int y = y1; y <= y2; y++) {
                            for (int x = x1; x <= x2; x++) {
                                if (y <= cut) c[y][x] = a[y][x];
                                else c[y][x] = b[y][x];
                            }
                        }
                        res.push_back(move(c));
                    }
                }

                memo[key] = res;
                return res;
            };

        vector<int> all(n);
        iota(all.begin(), all.end(), 0);
        auto sols = gen(0, 0, X - 1, Y - 1, all);

        // Remove duplicates
        vector<vector<vector<int>>> uniq;
        set<string> seen;
        for (auto &s : sols) {
            string key;
            key.reserve(X * Y * 3);
            for (int y = 0; y < Y; y++)
                for (int x = 0; x < X; x++) {
                    key += to_string(s[y][x]);
                    key += ',';
                }
            if (seen.insert(key).second) uniq.push_back(s);
        }

        if (uniq.empty()) {
            for (int y = 0; y < Y; y++) cout << string(X, '?') << "\n";
            continue;
        }

        for (int y = 0; y < Y; y++) {
            for (int x = 0; x < X; x++) {
                int v = uniq[0][y][x];
                bool same = true;
                for (int i = 1; i < (int)uniq.size(); i++) {
                    if (uniq[i][y][x] != v) {
                        same = false;
                        break;
                    }
                }
                if (same) cout << buyer[v];
                else cout << '?';
            }
            cout << "\n";
        }
    }

    return 0;
}

