                buyerInfo[i] = id + " " + sc.nextLine().trim();
                idToIndex.put(id, i);
            }

            int[][] grid = new int[Y][X];
            for (int y = 0; y < Y; y++) {
                for (int x = 0; x < X; x++) {
                    grid[y][x] = sc.nextInt();
                }
            }

            // For each buyer, find bounding box and verify rectangle
            int[] minX = new int[n+1], maxX = new int[n+1], minY = new int[n+1], maxY = new int[n+1];
            int[] count = new int[n+1];
            Arrays.fill(minX, X); Arrays.fill(minY, Y);
            Arrays.fill(maxX, -1); Arrays.fill(maxY, -1);

            for (int y = 0; y < Y; y++) {
                for (int x = 0; x < X; x++) {
                    int id = grid[y][x];
                    int idx = idToIndex.getOrDefault(id, -1);
                    if (idx == -1) continue;
                    count[idx]++;
                    if (x < minX[idx]) minX[idx] = x;
                    if (x > maxX[idx]) maxX[idx] = x;
                    if (y < minY[idx]) minY[idx] = y;
                    if (y > maxY[idx]) maxY[idx] = y;
