                int expected = (maxX[i]-minX[i]+1)*(maxY[i]-minY[i]+1);
                if (count[i] != expected) { valid = false; break; }
            }

            if (!valid) {
                System.out.println("NA");
            } else {
                for (int y = 0; y < Y; y++) {
                    for (int x = 0; x < X; x++) {
                        int id = grid[y][x];
