import java.io.*;
import java.util.*;

/*
 * AOJ style multiple-dataset solver.
 *
 * We have an X by Y grid. Each sold area belonging to the same buyer must form
 * one rectangle. The borders disappeared, and only buyer IDs written in cells remain.
 *
 * For each cell, determine which buyer uniquely owns it.
 * If a cell cannot be uniquely determined, output "NA" for that cell.
 *
 * Input format interpreted:
 *   X Y n
 *   n lines: buyer_id area
 *   Y lines: grid tokens (X tokens each), each token is a buyer_id written on that cell
 * Repeated until: 0 0 0
 *
 * For each buyer, we enumerate all rectangles:
 *   - area equals given area
 *   - every cell inside rectangle contains that buyer's ID in the observed grid
 *
 * Then we solve exact cover by buyers over all cells:
 *   choose one candidate rectangle per buyer, disjoint, covering all cells.
 *
 * For each cell, if across all valid global assignments the owner is always the same buyer,
 * output that buyer; otherwise output NA.
 *
 * Since each cell already contains some buyer's sign, and candidate rectangles only cover
 * cells with that same sign, the owner of a cell can only be that written buyer.
 * Therefore ambiguity for a cell means: that cell is not covered in all valid solutions.
 *
 * We compute for each candidate whether it can appear in at least one full solution,
 * using DFS with memoization over covered-cell mask and buyer index.
 *
 * Assumption: board is small enough for bitmask DP (typical original problem constraints).
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Candidate {
        long mask;
        Candidate(long mask) {
            this.mask = mask;
        }
    }

    static int X, Y, n, M;
    static String[] buyerId;
    static int[] area;
    static String[][] grid;
    static ArrayList<Candidate>[] candidates;
    static long fullMask;

    static HashMap<Long, Boolean>[] memo; // per buyer index: key = covered mask
    static boolean[] candidatePossible;

    static long key(int idx, long covered) {
        // not used now
        return (((long) idx) << 56) ^ covered;
    }

    static boolean can(int idx, long covered) {
        if (idx == n) return covered == fullMask;
        Boolean got = memo[idx].get(covered);
        if (got != null) return got;

        for (Candidate c : candidates[idx]) {
            if ((covered & c.mask) != 0) continue;
            if (can(idx + 1, covered | c.mask)) {
                memo[idx].put(covered, true);
                return true;
            }
        }
        memo[idx].put(covered, false);
        return false;
    }

    static boolean canForce(int idx, long covered, int forceBuyer, int forceCandIdx) {
        if (idx == n) return covered == fullMask;

        if (idx == forceBuyer) {
            Candidate c = candidates[idx].get(forceCandIdx);
            if ((covered & c.mask) != 0) return false;
            return can(idx + 1, covered | c.mask);
        }

        for (Candidate c : candidates[idx]) {
            if ((covered & c.mask) != 0) continue;
            if (can(idx + 1, covered | c.mask)) return true;
        }
        return false;
    }

    static int pos(int x, int y) {
        return y * X + x;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            X = Integer.parseInt(first);
            Y = fs.nextInt();
            n = fs.nextInt();
            if (X == 0 && Y == 0 && n == 0) break;

            M = X * Y;
            buyerId = new String[n];
            area = new int[n];
            for (int i = 0; i < n; i++) {
                buyerId[i] = fs.next();
                area[i] = fs.nextInt();
            }

            grid = new String[Y][X];
            for (int y = 0; y < Y; y++) {
                for (int x = 0; x < X; x++) {
                    grid[y][x] = fs.next();
                }
            }

            fullMask = (M == 64) ? -1L : ((1L << M) - 1);

            candidates = new ArrayList[n];
            for (int i = 0; i < n; i++) candidates[i] = new ArrayList<>();

            // Enumerate candidate rectangles for each buyer.
            for (int i = 0; i < n; i++) {
                int a = area[i];
                String id = buyerId[i];

                for (int h = 1; h * h <= a; h++) {
                    if (a % h != 0) continue;
                    int w = a / h;

                    addRectangles(i, id, w, h);
                    if (w != h) addRectangles(i, id, h, w);
                }
            }

            boolean impossible = false;
            for (int i = 0; i < n; i++) {
                if (candidates[i].isEmpty()) {
                    impossible = true;
                    break;
                }
            }

            String[][] ans = new String[Y][X];
            for (int y = 0; y < Y; y++) {
                Arrays.fill(ans[y], "NA");
            }

            if (!impossible) {
                memo = new HashMap[n + 1];
                for (int i = 0; i <= n; i++) memo[i] = new HashMap<>();

                boolean hasSolution = can(0, 0L);

                if (hasSolution) {
                    for (int i = 0; i < n; i++) {
                        for (int ci = 0; ci < candidates[i].size(); ci++) {
                            Candidate c = candidates[i].get(ci);
                            if (canForce(0, 0L, i, ci)) {
                                long mask = c.mask;
                                for (int p = 0; p < M; p++) {
                                    if (((mask >>> p) & 1L) != 0) {
                                        int y = p / X;
                                        int x = p % X;
                                        if (ans[y][x].equals("NA")) ans[y][x] = buyerId[i];
                                        else if (!ans[y][x].equals(buyerId[i])) ans[y][x] = "NA";
                                    }
                                }
                            }
                        }
                    }

                    // Cells not contained in any feasible candidate stay NA.
                    // Also ensure uniqueness: if there exists at least one feasible solution
                    // where a cell is uncovered by feasible candidates of its buyer, it remains NA.
                    // Since every valid solution covers every cell exactly once and only by same-id buyer,
                    // a cell is uniquely determined iff at least one feasible candidate of that buyer covers it.
                    // The above union is sufficient.
                }
            }

            for (int y = 0; y < Y; y++) {
                for (int x = 0; x < X; x++) {
                    if (x > 0) out.append(' ');
                    out.append(ans[y][x]);
                }
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static void addRectangles(int buyerIdx, String id, int w, int h) {
        for (int y0 = 0; y0 + h <= Y; y0++) {
            for (int x0 = 0; x0 + w <= X; x0++) {
                long mask = 0L;
                boolean ok = true;
                for (int y = y0; y < y0 + h && ok; y++) {
                    for (int x = x0; x < x0 + w; x++) {
                        if (!grid[y][x].equals(id)) {
                            ok = false;
                            break;
                        }
                        mask |= 1L << pos(x, y);
                    }
                }
                if (ok) candidates[buyerIdx].add(new Candidate(mask));
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    static int X, Y, n;
    static int[] a, b, c, d;
    static int[][] plot;
    static int[] buyerId; // 0 = unknown, 1..n = buyer number
    static boolean possible;
    static int[] assignedBuyer; // for each buyer, which rectangle they get (bitmask of plots)
    static List<int[]> solutions;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        while (true) {
            String line = br.readLine();
            if (line == null) break;
            String[] parts = line.trim().split("\\s+");
            X = Integer.parseInt(parts[0]);
            Y = Integer.parseInt(parts[1]);
            n = Integer.parseInt(parts[2]);
            if (X == 0 && Y == 0 && n == 0) break;

            a = new int[n];
            b = new int[n];
            c = new int[n];
            d = new int[n];
            for (int i = 0; i < n; i++) {
                parts = br.readLine().trim().split("\\s+");
                a[i] = Integer.parseInt(parts[0]);
                b[i] = Integer.parseInt(parts[1]);
                c[i] = Integer.parseInt(parts[2]);
                d[i] = Integer.parseInt(parts[3]);
            }

            plot = new int[Y][X];
            for (int y = 0; y < Y; y++) {
                line = br.readLine();
                // line may be empty or have spaces; handle carefully
                String[] nums = line.trim().split("\\s+");
                for (int x = 0; x < X; x++) {
                    plot[y][x] = Integer.parseInt(nums[x]);
                }
            }

            // Map each buyer to the set of plots they could occupy (based on size)
            // A buyer's rectangle has dimensions (c[i]-a[i]+1) x (d[i]-b[i]+1)
            // The plot must contain exactly that rectangle somewhere.
            // We will try to assign each buyer to a rectangle of the correct size that
            // contains only that buyer's id plots.

            // Precompute for each buyer the list of possible top-left corners
            List<List<int[]>> possiblePositions = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int w = c[i] - a[i] + 1;
                int h = d[i] - b[i] + 1;
                List<int[]> positions = new ArrayList<>();
                for (int y = 0; y + h <= Y; y++) {
                    for (int x = 0; x + w <= X; x++) {
                        boolean ok = true;
                        int expectedId = i + 1;
                        for (int dy = 0; dy < h && ok; dy++) {
                            for (int dx = 0; dx < w && ok; dx++) {
                                if (plot[y + dy][x + dx] != expectedId) {
                                    ok = false;
                                }
                            }
                        }
                        if (ok) {
                            positions.add(new int[]{x, y});
                        }
                    }
                }
                possiblePositions.add(positions);
            }

            // Check that each buyer has at least one possible position
            boolean impossible = false;
            for (int i = 0; i < n; i++) {
                if (possiblePositions.get(i).isEmpty()) {
                    impossible = true;
                    break;
                }
            }

            if (impossible) {
                System.out.println("NA");
                continue;
            }

            // Now we need to select one rectangle per buyer such that they don't overlap
            // and cover all plots with that buyer's id.
            // Since n <= 9 (small), we can try backtracking.
            // But we also need to consider that plots may have 0 (no buyer).
            // The assignment must cover exactly the plots that have id > 0 with the correct buyer.
            // So we precompute which plots belong to each buyer (by id).
            // Then we need to assign each buyer a rectangle that covers exactly those plots.

            // Precompute for each buyer the set of plots (bitmask of positions)
            int totalCells = X * Y;
            long[] buyerMask = new long[n];
            for (int i = 0; i < n; i++) {
                long mask = 0;
                int expectedId = i + 1;
                for (int y = 0; y < Y; y++) {
                    for (int x = 0; x < X; x++) {
                        if (plot[y][x] == expectedId) {
                            mask |= (1L << (y * X + x));
                        }
                    }
                }
                buyerMask[i] = mask;
            }

            // For each possible rectangle for a buyer, compute its mask
            List<List<Long>> rectMasks = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int w = c[i] - a[i] + 1;
                int h = d[i] - b[i] + 1;
                List<Long> masks = new ArrayList<>();
                for (int[] pos : possiblePositions.get(i)) {
                    int x = pos[0], y = pos[1];
                    long mask = 0;
                    for (int dy = 0; dy < h; dy++) {
                        for (int dx = 0; dx < w; dx++) {
                            mask |= (1L << ((y + dy) * X + (x + dx)));
                        }
                    }
                    masks.add(mask);
                }
                rectMasks.add(masks);
            }

            // Backtracking
            solutions = new ArrayList<>();
            long usedMask = 0;
            int[] assignment = new int[n]; // index of chosen rectangle for each buyer
            boolean[] usedRect = new boolean[n]; // not needed, we check overlap via usedMask
            backtrack(0, rectMasks, buyerMask, usedMask, assignment, new boolean[n]);

            if (solutions.size() == 1) {
                int[] sol = solutions.get(0);
                // Build output grid
                int[][] result = new int[Y][X];
                for (int i = 0; i < n; i++) {
                    int rectIdx = sol[i];
                    long mask = rectMasks.get(i).get(rectIdx);
                    int buyerNum = i + 1;
                    for (int y = 0; y < Y; y++) {
                        for (int x = 0; x < X; x++) {
                            if ((mask & (1L << (y * X + x))) != 0) {
                                result[y][x] = buyerNum;
                            }
                        }
                    }
                }
                // Output
                for (int y = 0; y < Y; y++) {
                    StringBuilder sb = new StringBuilder();
                    for (int x = 0; x < X; x++) {
                        if (x > 0) sb.append(" ");
                        sb.append(result[y][x]);
                    }
                    System.out.println(sb.toString());
                }
            } else {
                System.out.println("NA");
            }
        }
    }

    static void backtrack(int buyerIdx, List<List<Long>> rectMasks, long[] buyerMask,
                          long usedMask, int[] assignment, boolean[] usedBuyer) {
        if (buyerIdx == n) {
            // Check that all plots with id>0 are covered exactly once
            // (already ensured by rectangle covering exactly buyer's plots)
            // But we also need to ensure no extra plots are covered.
            // Actually the rectangles must exactly match the buyer's plots.
            // Since we only consider rectangles that contain exactly the buyer's plots,
            // this is already satisfied.
            // However we must also ensure that plots with id 0 are not covered.
            // Our rectangles only contain plots with the correct id (since we checked),
            // so that's fine.
            // But we also need to ensure that all plots with id>0 are covered by exactly one rectangle.
            // Since we assign each buyer exactly one rectangle covering their plots,
            // and plots are disjoint (different ids), this holds.
            // So we just record the assignment.
            solutions.add(assignment.clone());
            return;
        }

        List<Long> masks = rectMasks.get(buyerIdx);
        long targetMask = buyerMask[buyerIdx];
        for (int i = 0; i < masks.size(); i++) {
            long mask = masks.get(i);
            // The rectangle must cover exactly the buyer's plots
            if ((mask & targetMask) != targetMask) continue; // must cover all buyer's plots
            if ((mask & ~targetMask) != 0) continue; // must not cover other plots (with different ids or 0)
            // Check overlap with already used rectangles
            if ((mask & usedMask) != 0) continue;
            assignment[buyerIdx] = i;
            backtrack(buyerIdx + 1, rectMasks, buyerMask, usedMask | mask, assignment, usedBuyer);
            if (solutions.size() > 1) return; // early exit if multiple solutions
        }
    }
}

import sys

def solve():
    it = iter(sys.stdin.read().splitlines())
    out = []

    for line in it:
        if not line.strip():
            continue
        X, Y, n = map(int, line.split())
        if X == 0 and Y == 0 and n == 0:
            break

        buyers = []
        area_sum = 0
        for _ in range(n):
            name, a = next(it).split()
            a = int(a)
            buyers.append((name, a))
            area_sum += a

        grid = [list(next(it).rstrip('\n')) for _ in range(Y)]

        # Sanity: total area must match
        if area_sum != X * Y:
            out.append("NA")
            continue

        # positions of each sign character on grid
        pos = {}
        ok = True
        for y in range(Y):
            if len(grid[y]) != X:
                ok = False
                break
            for x in range(X):
                c = grid[y][x]
                if c in pos:
                    ok = False  # sign must be unique
                    break
                pos[c] = (x, y)
            if not ok:
                break

        if not ok:
            out.append("NA")
            continue

        # Each buyer name must correspond to exactly one sign on the map
        rect_candidates = []
        for name, area in buyers:
            if len(name) != 1 or name not in pos:
                ok = False
                break
            sx, sy = pos[name]

            cand = []
            # enumerate all rectangles of given area containing (sx, sy)
            for w in range(1, X + 1):
                if area % w != 0:
                    continue
                h = area // w
                if h > Y:
                    continue

                x0_min = max(0, sx - w + 1)
                x0_max = min(sx, X - w)
                y0_min = max(0, sy - h + 1)
                y0_max = min(sy, Y - h)
                for x0 in range(x0_min, x0_max + 1):
                    for y0 in range(y0_min, y0_max + 1):
                        cand.append((x0, y0, x0 + w, y0 + h))  # [x0,x1), [y0,y1)
            if not cand:
                ok = False
                break
            rect_candidates.append(cand)

        if not ok:
            out.append("NA")
            continue

        # Exact cover by rectangles: pairwise disjoint and cover all cells.
        # Backtracking with pruning using occupancy bitmask.
        total_cells = X * Y
        full_mask = (1 << total_cells) - 1

        def rect_mask(r):
            x0, y0, x1, y1 = r
            m = 0
            for yy in range(y0, y1):
                base = yy * X
                for xx in range(x0, x1):
                    m |= 1 << (base + xx)
            return m

        cand_masks = []
        for cand in rect_candidates:
            lst = []
            for r in cand:
                lst.append((r, rect_mask(r)))
            cand_masks.append(lst)

        # Order buyers by fewest candidates
        order = sorted(range(n), key=lambda i: len(cand_masks[i]))

        solution = [None] * n
        count = 0
        first_solution = None

        # For stronger pruning, precompute area remaining
        areas = [buyers[i][1] for i in range(n)]

        def dfs(k, used_mask):
            nonlocal count, first_solution
            if count > 1:
                return
            if k == n:
                if used_mask == full_mask:
                    count += 1
                    if count == 1:
                        first_solution = solution[:]
                return

            i = order[k]
            # Remaining area check
            used_area = used_mask.bit_count()
            rem_area = sum(areas[order[t]] for t in range(k, n))
            if used_area + rem_area != total_cells:
                return

            for r, m in cand_masks[i]:
                if used_mask & m:
                    continue
                solution[i] = r
                dfs(k + 1, used_mask | m)
                solution[i] = None
                if count > 1:
                    return

        dfs(0, 0)

        if count != 1:
            out.append("NA")
            continue

        # Build output map with buyer names
        ans = [['?'] * X for _ in range(Y)]
        for i, r in enumerate(first_solution):
            x0, y0, x1, y1 = r
            ch = buyers[i][0]
            for yy in range(y0, y1):
                for xx in range(x0, x1):
                    ans[yy][xx] = ch

        out.extend(''.join(row) for row in ans)

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

